<?php
namespace App\Services;
use Illuminate\Http\Request;
use Illuminate\Support\Facades\DB;
final class PayrollLedger {
 public function __construct(public PayrollAccess $pay,private SchoolPayroll $payroll){}
 public function advanceList(Request $r,int $campus):array{[$sid]=$this->pay->context($r);abort_unless($this->pay->finance($r),403);$this->pay->campus($r,$campus);$rows=DB::table('staff_advances as a')->join('staff_profiles as p','p.id','=','a.staff_profile_id')->join('school_memberships as m','m.id','=','p.membership_id')->join('users as u','u.id','=','m.user_id')->where('a.school_id',$sid)->where('a.campus_id',$campus)->orderByDesc('a.id')->get(['a.*','p.employee_no','u.name']);foreach($rows as $row)$row->outstanding=$row->status==='paid'?$this->pay->money($this->payroll->advanceBalance($sid,$row)):'0.00';return ['rows'=>$rows];}
 public function advance(Request $r,array $d):array{return DB::transaction(function()use($r,$d){$sid=$this->pay->lock($r,'payroll.manage');$p=$this->pay->staff($r,$d['staff_profile_id']);$this->pay->campus($r,$d['campus_id'],true);if(!DB::table('staff_employments')->where('school_id',$sid)->where('staff_profile_id',$p->id)->where('campus_id',$d['campus_id'])->where('starts_on','<=',$d['requested_on'])->where(fn($q)=>$q->whereNull('ends_on')->orWhere('ends_on','>=',$d['requested_on']))->exists())$this->pay->fail('The advance needs a staff appointment at this campus/request date.');if($d['requested_on']>$this->pay->today())$this->pay->fail('Advance request date cannot be in the future.');if($this->pay->cents($d['monthly_recovery'])>$this->pay->cents($d['amount']))$this->pay->fail('Monthly recovery cannot exceed the advance amount.');$id=DB::table('staff_advances')->insertGetId($d+['school_id'=>$sid,'status'=>'requested','created_at'=>now(),'updated_at'=>now()]);$this->pay->access->audit($r,'payroll.advance_requested','staff_advances',$id,$d);return ['id'=>$id,'message'=>'Advance requested for approval.'];});}
 public function advanceAction(Request $r,int $id,array $d):array{return DB::transaction(function()use($r,$id,$d){$sid=$this->pay->lock($r,$d['action']==='disburse'?'payroll.manage':'payroll.approve');$a=DB::table('staff_advances')->where('school_id',$sid)->where('id',$id)->first()??abort(404);if(!$a->campus_id||!$a->requested_on)$this->pay->fail('Legacy advance metadata requires review before this action.');$this->pay->campus($r,$a->campus_id,true);if($d['action']==='disburse'&&$a->status==='paid'&&$a->disbursement_key===($d['idempotency_key']??null)){if($a->paid_on!==($d['paid_on']??null)||$a->method!==($d['method']??null)||$a->bank_account_id!=($d['bank_account_id']??null)||$a->reference!==($d['reference']??null))$this->pay->fail('This disbursement key belongs to different details.');return ['message'=>'Advance disbursement already recorded.'];}if($a->lock_version!=$d['lock_version'])$this->pay->fail('Advance changed. Reload before acting.');$values=['lock_version'=>$a->lock_version+1,'updated_at'=>now()];if($d['action']==='approve'){if($a->status!=='requested')$this->pay->fail('Only a requested advance can be approved.');$values+=['status'=>'approved','approved_by'=>$this->pay->access->membership($r)->id];}elseif($d['action']==='cancel'){if(!in_array($a->status,['requested','approved','paid'],true))$this->pay->fail('This advance is already closed.');if($a->status==='paid'&&$this->payroll->advanceBalance($sid,$a)!==$this->pay->cents($a->amount))$this->pay->fail('An advance with booked recoveries cannot be voided until those recoveries are restored through approved recovery-refund adjustments.');$values['status']='void';}else{if($a->status!=='approved'||!$a->approved_by)$this->pay->fail('Approve this advance before disbursement.');if($d['paid_on']<$a->requested_on||$d['paid_on']>$this->pay->today())$this->pay->fail('Choose a disbursement date between request date and today.');$this->pay->bank($r,$d['bank_account_id']??null,$a->campus_id,$d['method']);if(DB::table('staff_advances')->where('school_id',$sid)->where('disbursement_key',$d['idempotency_key'])->where('id','<>',$a->id)->exists())$this->pay->fail('This disbursement key is already used.');$values+=['status'=>'paid','paid_on'=>$d['paid_on'],'method'=>$d['method'],'bank_account_id'=>$d['bank_account_id']??null,'reference'=>$d['reference']??null,'disbursement_key'=>$d['idempotency_key']];}DB::table('staff_advances')->where('school_id',$sid)->where('id',$id)->update($values);$this->pay->access->audit($r,'payroll.advance_'.$d['action'],'staff_advances',$id,['reason'=>$d['reason']??null,'before'=>$a,'after'=>$values]);return ['message'=>match($d['action']){'approve'=>'Advance approved.','cancel'=>'Advance voided with audit history.','disburse'=>'Advance disbursement recorded. Recovery starts from the following payroll month.'}];});}
 public function totals(int $sid,object $item):array{$adjustments=DB::table('payroll_adjustments')->where('school_id',$sid)->where('payroll_item_id',$item->id)->where('status','approved')->get();$credit=0;$debit=0;foreach($adjustments as $a)if($a->kind==='debit')$debit+=$this->pay->cents($a->amount);else $credit+=$this->pay->cents($a->amount);$paid=0;$payments=DB::table('salary_payment_allocations as a')->join('salary_payments as p','p.id','=','a.salary_payment_id')->leftJoin('salary_payment_reversals as v','v.salary_payment_id','=','p.id')->where('a.school_id',$sid)->where('a.payroll_item_id',$item->id)->get(['a.amount','p.amount as payment_amount','v.amount as reversed']);foreach($payments as $p){if($p->reversed!==null){if($this->pay->cents($p->reversed)!==$this->pay->cents($p->payment_amount))$this->pay->fail('A salary payment has an unsupported partial legacy reversal. Reconcile it before proceeding.');}else $paid+=$this->pay->cents($p->amount);}$net=$this->pay->cents($item->net_amount)+$credit-$debit;if($net<0||$paid>$net)$this->pay->fail('A legacy salary balance needs reconciliation.');return ['credits'=>$this->pay->money($credit),'debits'=>$this->pay->money($debit),'payable'=>$this->pay->money($net),'paid'=>$this->pay->money($paid),'balance'=>$this->pay->money($net-$paid)];}
 public function runs(Request $r,array $d){[$sid]=$this->pay->context($r);abort_unless($this->pay->finance($r),403);$this->pay->campus($r,$d['campus_id']);return DB::table('payroll_runs')->where('school_id',$sid)->where('campus_id',$d['campus_id'])->orderByDesc('period')->orderByDesc('id')->paginate(20);}
 public function run(Request $r,int $id):array{[$sid]=$this->pay->context($r);abort_unless($this->pay->finance($r),403);$run=DB::table('payroll_runs')->where('school_id',$sid)->where('id',$id)->first()??abort(404);$campus=$this->pay->campus($r,$run->campus_id);$run->snapshot=$run->snapshot?json_decode($run->snapshot,true):null;$items=DB::table('payroll_items')->where('school_id',$sid)->where('payroll_run_id',$id)->orderBy('id')->get();foreach($items as $item){$item->snapshot=$item->snapshot?json_decode($item->snapshot,true):null;$item->totals=$run->status==='approved'?$this->totals($sid,$item):null;}return ['run'=>$run,'campus'=>$campus,'items'=>$items,'can_manage'=>$this->pay->can($r,'payroll.manage'),'can_approve'=>$this->pay->can($r,'payroll.approve')];}
 public function payslip(Request $r,int $id):array{[$sid]=$this->pay->context($r);[$item,$run]=$this->pay->item($r,$id,true);if($run->status!=='approved'||!$item->snapshot)$this->pay->fail('An approved, archived payroll item is required for a payslip.');$item->snapshot=json_decode($item->snapshot,true);$adjustments=DB::table('payroll_adjustments as a')->join('school_memberships as m','m.id','=','a.requested_by')->join('users as u','u.id','=','m.user_id')->where('a.school_id',$sid)->where('a.payroll_item_id',$id)->orderBy('a.id')->get(['a.*','u.name as requested_by_name']);$payments=DB::table('salary_payment_allocations as a')->join('salary_payments as p','p.id','=','a.salary_payment_id')->leftJoin('salary_payment_reversals as v','v.salary_payment_id','=','p.id')->where('a.school_id',$sid)->where('a.payroll_item_id',$id)->orderByDesc('p.id')->get(['p.id','p.amount','p.paid_at','p.method','p.reference','a.amount as allocated','v.reversed_at','v.reason as reversal_reason']);$recoveries=DB::table('advance_recoveries')->where('school_id',$sid)->where('payroll_item_id',$id)->get();return ['item'=>$item,'run'=>$run,'totals'=>$this->totals($sid,$item),'adjustments'=>$adjustments,'payments'=>$payments,'recoveries'=>$recoveries,'can_manage'=>$this->pay->can($r,'payroll.manage'),'can_approve'=>$this->pay->can($r,'payroll.approve')];}
 public function adjustment(Request $r,array $d):array{return DB::transaction(function()use($r,$d){$sid=$this->pay->lock($r,'payroll.manage');[$item,$run]=$this->pay->item($r,$d['payroll_item_id']);if($run->status!=='approved')$this->pay->fail('Adjustments belong to approved payroll only.');if($d['kind']==='recovery_refund'){$recovery=DB::table('advance_recoveries')->where('school_id',$sid)->where('id',$d['advance_recovery_id']??0)->where('payroll_item_id',$item->id)->first()??abort(404);if($this->pay->cents($d['amount'])>$this->pay->cents($recovery->amount))$this->pay->fail('A recovery refund cannot exceed the original recovery.');}elseif(!empty($d['advance_recovery_id']))$this->pay->fail('Only recovery-refund adjustments select an advance recovery.');$id=DB::table('payroll_adjustments')->insertGetId($d+['school_id'=>$sid,'status'=>'requested','requested_by'=>$this->pay->access->membership($r)->id,'created_at'=>now(),'updated_at'=>now()]);$this->pay->access->audit($r,'payroll.adjustment_requested','payroll_adjustments',$id,$d);return ['message'=>'Payroll adjustment requested for approval.','id'=>$id];});}
 public function reviewAdjustment(Request $r,int $id,array $d):array{return DB::transaction(function()use($r,$id,$d){$sid=$this->pay->lock($r,'payroll.approve');$a=DB::table('payroll_adjustments')->where('school_id',$sid)->where('id',$id)->first()??abort(404);[$item,$run]=$this->pay->item($r,$a->payroll_item_id);if($a->status!=='requested')$this->pay->fail('This adjustment was already reviewed.');if($d['action']==='approve'){$totals=$this->totals($sid,$item);if($a->kind==='debit'&&$this->pay->cents($a->amount)>$this->pay->cents($totals['balance']))$this->pay->fail('The debit would reduce entitlement below recorded salary payments. Reverse an erroneous payment first.');if($a->kind==='recovery_refund'){$rec=DB::table('advance_recoveries')->where('school_id',$sid)->where('id',$a->advance_recovery_id)->where('payroll_item_id',$item->id)->first()??abort(404);$used=(int)DB::table('payroll_adjustments')->where('school_id',$sid)->where('advance_recovery_id',$rec->id)->where('kind','recovery_refund')->where('status','approved')->selectRaw('COALESCE(SUM(amount)*100,0) as n')->value('n');if($used+$this->pay->cents($a->amount)>$this->pay->cents($rec->amount))$this->pay->fail('Approved refunds would exceed this advance recovery.');}}$status=$d['action']==='approve'?'approved':'rejected';DB::table('payroll_adjustments')->where('school_id',$sid)->where('id',$id)->update(['status'=>$status,'approved_by'=>$this->pay->access->membership($r)->id,'reviewed_at'=>now(),'updated_at'=>now()]);$this->pay->access->audit($r,'payroll.adjustment_'.$status,'payroll_adjustments',$id,['reason'=>$d['reason'],'kind'=>$a->kind,'amount'=>$a->amount]);return ['message'=>'Payroll adjustment '.$status.'.'];});}
 public function payment(Request $r,array $d):array{return DB::transaction(function()use($r,$d){$sid=$this->pay->lock($r,'payroll.manage');$this->pay->campus($r,$d['campus_id'],true);$this->pay->staff($r,$d['staff_profile_id']);$this->pay->bank($r,$d['bank_account_id']??null,$d['campus_id'],$d['method']);$allocations=collect($d['allocations'])->map(fn($x)=>['payroll_item_id'=>(int)$x['payroll_item_id'],'amount'=>$this->pay->money($this->pay->cents($x['amount']))])->sortBy('payroll_item_id')->values()->all();$canonical=['campus_id'=>(int)$d['campus_id'],'staff_profile_id'=>(int)$d['staff_profile_id'],'amount'=>$this->pay->money($this->pay->cents($d['amount'])),'paid_on'=>$d['paid_on'],'method'=>$d['method'],'bank_account_id'=>empty($d['bank_account_id'])?null:(int)$d['bank_account_id'],'reference'=>$d['reference']??null,'allocations'=>$allocations];$hash=hash('sha256',json_encode($canonical));$old=DB::table('salary_payments')->where('school_id',$sid)->where('idempotency_key',$d['idempotency_key'])->first();if($old){$this->pay->campus($r,$old->campus_id);if($old->request_hash!==$hash)$this->pay->fail('This payment key is already used for different details.');return ['message'=>'Salary payment already recorded.','id'=>$old->id];}if($d['paid_on']>$this->pay->today())$this->pay->fail('Salary payment date cannot be in the future.');$sum=0;$lines=[];foreach($allocations as $a){[$item,$run]=$this->pay->item($r,$a['payroll_item_id']);if($run->status!=='approved'||$run->campus_id!=$d['campus_id']||$item->staff_profile_id!=$d['staff_profile_id'])$this->pay->fail('Allocate only approved payroll for the selected employee/campus.');if($d['paid_on']<$run->period)$this->pay->fail('Payment cannot predate its payroll month.');$n=$this->pay->cents($a['amount']);$totals=$this->totals($sid,$item);if($n>$this->pay->cents($totals['balance']))$this->pay->fail('Payment allocation exceeds outstanding salary.');$sum+=$n;$lines[]=['payroll_item_id'=>$item->id,'period'=>$run->period,'amount'=>$a['amount']];}if($sum!==$this->pay->cents($d['amount']))$this->pay->fail('Allocation total must match the payment amount.');$p=$this->pay->staff($r,$d['staff_profile_id']);$school=DB::table('schools')->where('id',$sid)->first();$snapshot=['school_name'=>$school->name,'school_code'=>$school->code,'staff_name'=>$p->name,'employee_no'=>$p->employee_no,'lines'=>$lines];$id=DB::table('salary_payments')->insertGetId(['school_id'=>$sid,'campus_id'=>$d['campus_id'],'staff_profile_id'=>$p->id,'bank_account_id'=>$d['bank_account_id']??null,'amount'=>$d['amount'],'paid_at'=>$d['paid_on'].' 12:00:00','method'=>$d['method'],'recorded_by'=>$this->pay->access->membership($r)->id,'reference'=>$d['reference']??null,'idempotency_key'=>$d['idempotency_key'],'request_hash'=>$hash,'snapshot'=>json_encode($snapshot),'created_at'=>now(),'updated_at'=>now()]);foreach($allocations as $a)DB::table('salary_payment_allocations')->insert($a+['school_id'=>$sid,'salary_payment_id'=>$id,'created_at'=>now(),'updated_at'=>now()]);$this->pay->access->audit($r,'payroll.salary_paid','salary_payments',$id,['amount'=>$d['amount'],'staff_profile_id'=>$p->id,'allocations'=>$allocations]);return ['message'=>'Salary payment recorded.','id'=>$id];});}
 public function reversePayment(Request $r,int $id,array $d):array{return DB::transaction(function()use($r,$id,$d){$sid=$this->pay->lock($r,'payroll.approve');$p=DB::table('salary_payments')->where('school_id',$sid)->where('id',$id)->first()??abort(404);$this->pay->campus($r,$p->campus_id);if(DB::table('salary_payment_reversals')->where('school_id',$sid)->where('salary_payment_id',$id)->exists())return ['message'=>'Salary payment is already reversed.'];DB::table('salary_payment_reversals')->insert(['school_id'=>$sid,'salary_payment_id'=>$id,'amount'=>$p->amount,'reason'=>$d['reason'],'approved_by'=>$this->pay->access->membership($r)->id,'reversed_at'=>now(),'created_at'=>now(),'updated_at'=>now()]);$this->pay->access->audit($r,'payroll.salary_payment_reversed','salary_payments',$id,['amount'=>$p->amount,'reason'=>$d['reason']]);return ['message'=>'Salary payment reversed. Original receipt and correction history were retained.'];});}
 public function receipt(Request $r,int $id):array{[$sid,$m]=$this->pay->context($r);$p=DB::table('salary_payments')->where('school_id',$sid)->where('id',$id)->first()??abort(404);$staff=DB::table('staff_profiles')->where('school_id',$sid)->where('id',$p->staff_profile_id)->first()??abort(404);if(!($this->pay->can($r,'staff.self')&&$staff->membership_id===$m->id)){abort_unless($this->pay->finance($r),403);$this->pay->campus($r,$p->campus_id);}if(!$p->snapshot)$this->pay->fail('Legacy salary payment receipt needs review.');$p->snapshot=json_decode($p->snapshot,true);$reversal=DB::table('salary_payment_reversals')->where('school_id',$sid)->where('salary_payment_id',$id)->first();return ['payment'=>$p,'reversal'=>$reversal];}
 public function self(Request $r):array{[$sid,$m]=$this->pay->context($r,'staff.self');$p=DB::table('staff_profiles')->where('school_id',$sid)->where('membership_id',$m->id)->first();$items=$p?DB::table('payroll_items as i')->join('payroll_runs as r','r.id','=','i.payroll_run_id')->where('i.school_id',$sid)->where('i.staff_profile_id',$p->id)->where('r.status','approved')->orderByDesc('r.period')->limit(36)->get(['i.id','i.net_amount','r.period']):collect();return ['staff'=>$p,'payslips'=>$items];}
}
